// Checks World/Astro.cpp against astro_reference.csv (generated by PyEphem + zoneinfo).
#include "../../Source/BudapestSim/World/Astro.h"

#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <sstream>
#include <string>

static int Failures = 0;
#define EXPECT(Cond, ...)                                                   \
	do                                                                      \
	{                                                                       \
		if (!(Cond))                                                        \
		{                                                                   \
			std::printf("FAIL line %d: ", __LINE__);                        \
			std::printf(__VA_ARGS__);                                       \
			std::printf("\n");                                              \
			++Failures;                                                     \
		}                                                                   \
	} while (0)

static double AngleDiff(double A, double B)
{
	double D = std::fmod(A - B, 360.0);
	if (D > 180.0) D -= 360.0;
	if (D < -180.0) D += 360.0;
	return std::fabs(D);
}

int main(int argc, char** argv)
{
	const double Lat = 47.4977, Lon = 19.0541;
	std::ifstream In(argc > 1 ? argv[1] : "astro_reference.csv");
	std::string Line;
	std::getline(In, Line); // header

	int Rows = 0;
	double WorstSunEl = 0, WorstSunAz = 0, WorstMoonEl = 0, WorstMoonAz = 0, WorstIllum = 0;
	while (std::getline(In, Line))
	{
		std::stringstream Cols(Line);
		std::string Cell;
		double V[7];
		for (int I = 0; I < 7; ++I)
		{
			std::getline(Cols, Cell, ',');
			V[I] = std::atof(Cell.c_str());
		}
		const long long Unix = static_cast<long long>(V[0]);
		++Rows;

		const Astro::FSkyBody Sun = Astro::SunPosition(static_cast<double>(Unix), Lat, Lon);
		WorstSunEl = std::fmax(WorstSunEl, std::fabs(Sun.ElevationDegrees - V[1]));
		// Azimuth is ill-conditioned near the zenith; this latitude never reaches it, so check it directly.
		WorstSunAz = std::fmax(WorstSunAz, AngleDiff(Sun.AzimuthDegrees, V[2]));

		const Astro::FMoon Moon = Astro::MoonPosition(static_cast<double>(Unix), Lat, Lon);
		WorstMoonEl = std::fmax(WorstMoonEl, std::fabs(Moon.ElevationDegrees - V[3]));
		WorstMoonAz = std::fmax(WorstMoonAz, AngleDiff(Moon.AzimuthDegrees, V[4]));
		WorstIllum = std::fmax(WorstIllum, std::fabs(Moon.IlluminatedFraction - V[5]));

		EXPECT(Astro::BudapestUtcOffsetHours(Unix) == static_cast<int>(V[6]), "UTC offset at %lld: got %d want %d",
			Unix, Astro::BudapestUtcOffsetHours(Unix), static_cast<int>(V[6]));
	}

	EXPECT(Rows > 1000, "only %d rows", Rows);
	EXPECT(WorstSunEl < 0.05, "sun elevation off by %.4f deg", WorstSunEl);
	EXPECT(WorstSunAz < 0.1, "sun azimuth off by %.4f deg", WorstSunAz);
	// The moon series is truncated and includes a first-order parallax correction.
	EXPECT(WorstMoonEl < 0.5, "moon elevation off by %.4f deg", WorstMoonEl);
	// Azimuth parallax is not modelled (up to ~0.7 deg, about the width of the moon disc).
	EXPECT(WorstMoonAz < 1.0, "moon azimuth off by %.4f deg", WorstMoonAz);
	EXPECT(WorstIllum < 0.02, "moon illumination off by %.4f", WorstIllum);

	// Sanity anchors that do not depend on the reference file.
	const long long SolsticeNoon = Astro::UnixFromUtc(2026, 6, 21, 10, 0, 0);
	EXPECT(Astro::BudapestUtcOffsetHours(SolsticeNoon) == 2, "summer offset");
	EXPECT(Astro::BudapestUtcOffsetHours(Astro::UnixFromUtc(2026, 12, 21, 12, 0, 0)) == 1, "winter offset");
	EXPECT(std::fabs(Astro::BudapestLocalHours(static_cast<double>(Astro::UnixFromUtc(2026, 6, 21, 10, 0, 0))) - 12.0) < 1e-9, "local hours 12:00 CEST");
	EXPECT(std::fabs(Astro::BudapestLocalHours(static_cast<double>(Astro::UnixFromUtc(2026, 12, 21, 23, 30, 0))) - 0.5) < 1e-9, "local hours wrap past midnight");
	EXPECT(Astro::UnixFromUtc(1970, 1, 1, 0, 0, 0) == 0, "epoch");
	EXPECT(Astro::UnixFromUtc(2000, 3, 1, 0, 0, 0) == 951868800LL, "2000-03-01");
	const Astro::FSkyBody Noon = Astro::SunPosition(static_cast<double>(Astro::UnixFromUtc(2026, 6, 21, 10, 46, 0)), Lat, Lon);
	EXPECT(Noon.ElevationDegrees > 65.0 && Noon.ElevationDegrees < 67.0, "midsummer noon elevation %.2f (expect ~66)", Noon.ElevationDegrees);

	if (Failures == 0)
	{
		std::printf("OK astro: %d rows. worst error: sun el %.4f az %.4f deg; moon el %.3f az %.3f deg, illum %.4f\n",
			Rows, WorstSunEl, WorstSunAz, WorstMoonEl, WorstMoonAz, WorstIllum);
		return 0;
	}
	std::printf("FAILED: %d\n", Failures);
	return 1;
}
